import csv,json,collections,datetime as d
rows=list(csv.DictReader(open('inputs/shipments.csv')))
car=json.load(open('inputs/carriers.json'))
print(len(rows), collections.Counter(r['carrier_code'] for r in rows))
ids=collections.Counter(r['shipment_id'] for r in rows); print('dups',[k for k,v in ids.items() if v>1])
bad=[]
for r in rows:
  try: d.date.fromisoformat(r['promised']); d.date.fromisoformat(r['delivered'])
  except Exception: bad.append(r)
print('bad dates',len(bad), bad[:5])
print('unknown codes', set(r['carrier_code'] for r in rows)-set(car))
ok=0;n=0;delays=collections.defaultdict(list)
for r in rows:
  try:
    p=d.date.fromisoformat(r['promised'].strip()); a=d.date.fromisoformat(r['delivered'].strip())
  except Exception: continue
  n+=1; ok+= a<=p; delays[r['carrier_code']].append((a-p).days)
print(n, ok, round(ok/n,4))
for c,v in sorted(delays.items(), key=lambda x:-sum(x[1])/len(x[1])): print(c, car.get(c), len(v), sum(v)/len(v))
